'use client'

import { useState, useEffect } from 'react'
import { sdkFetch } from '../client'

/**
 * An update list as the public feed sees it. Timestamps are stripped
 * server-side — this is the whole shape.
 */
export interface UpdateListSummary {
	id: string
	name: string
	slug: string
	description: string | null
}

/**
 * A published update item. Dates arrive as ISO strings because the payload is
 * JSON; pass them to `new Date(...)` before formatting.
 */
export interface UpdateFeedItem {
	id: string
	title: string
	/** Markdown source. */
	body: string
	imageUrl: string | null
	eventDate: string | null
	publishedAt: string | null
}

interface UseUpdateListsResult {
	lists: UpdateListSummary[]
	loading: boolean
	error: string | null
}

/** List every update feed the tenant publishes, ordered by name. */
export function useUpdateLists(): UseUpdateListsResult {
	const [lists, setLists] = useState<UpdateListSummary[]>([])
	const [loading, setLoading] = useState(true)
	const [error, setError] = useState<string | null>(null)

	useEffect(() => {
		let cancelled = false

		async function load() {
			setLoading(true)
			const res = await sdkFetch<{ lists: UpdateListSummary[] }>('/updates?action=lists')
			if (cancelled) return
			if (res.error) {
				setError(res.error)
			} else {
				setError(null)
				setLists(res.data?.lists ?? [])
			}
			setLoading(false)
		}

		void load()
		return () => {
			cancelled = true
		}
	}, [])

	return { lists, loading, error }
}

export interface UseUpdatesOptions {
	/** Number of items to fetch. Clamped server-side to 1..100; defaults to 20. */
	limit?: number
}

interface UseUpdatesResult {
	items: UpdateFeedItem[]
	/** Meta for the requested list, or null while loading / when it does not exist. */
	list: UpdateListSummary | null
	loading: boolean
	error: string | null
}

/**
 * Published items of one update list, newest first. An unknown `listSlug`
 * resolves to an error (the route 404s) rather than an empty feed, so the
 * caller can tell "no items yet" apart from "wrong slug".
 */
export function useUpdates(listSlug: string, options?: UseUpdatesOptions): UseUpdatesResult {
	const [items, setItems] = useState<UpdateFeedItem[]>([])
	const [list, setList] = useState<UpdateListSummary | null>(null)
	const [loading, setLoading] = useState(true)
	const [error, setError] = useState<string | null>(null)
	const limit = options?.limit

	useEffect(() => {
		let cancelled = false

		async function load() {
			setLoading(true)
			const params = new URLSearchParams({ action: 'items', list: listSlug })
			if (limit !== undefined) params.set('limit', String(limit))
			const res = await sdkFetch<{ list: UpdateListSummary | null; items: UpdateFeedItem[] }>(
				`/updates?${params.toString()}`,
			)
			if (cancelled) return
			if (res.error) {
				setError(res.error)
			} else {
				setError(null)
				setList(res.data?.list ?? null)
				setItems(res.data?.items ?? [])
			}
			setLoading(false)
		}

		void load()
		return () => {
			cancelled = true
		}
	}, [listSlug, limit])

	return { items, list, loading, error }
}
