// SDK-side JSON-LD: the thin adapter from a tenant's stored content rows to the
// shared schema.org builders in `@growth-engine/types/json-ld`.
//
// The BUILDERS deliberately do not live here any more. The site crawl flags
// `missing_structured_data` on pages this engine does not host, and the
// site-health loop now hands the owner a ready-to-paste `<script>` for those —
// generated from the SAME builders this file calls. Had the builders stayed in
// a browser-only React package, the platform would have needed its own copy,
// and the markup in the brief would have drifted from the markup on the hosted
// pages within a release or two.
//
// What is left here is the mapping only: BlogPost/BlogAuthor/BusinessConfig
// (Turso rows) → the builders' structural inputs.

import type { BlogPost, BlogAuthor, BusinessConfig } from '@growth-engine/types'
import {
	blogBreadcrumbs,
	buildArticleLd,
	buildBlogPostingGraph,
	buildOrganizationLd,
	type BreadcrumbItem,
	type BusinessLdInput,
	type JsonLdObject,
} from '@growth-engine/types/json-ld'

export type { JsonLdObject, BreadcrumbItem }
export {
	buildBreadcrumbListLd,
	buildFaqPageLd,
	buildWebSiteLd,
	extractFaqPairs,
	renderJsonLdScriptTag,
	serializeJsonLd,
	type FaqPair,
} from '@growth-engine/types/json-ld'

/** PURE. A stored business_config row as the shared builders want it. */
function toBusinessInput(config: BusinessConfig): BusinessLdInput {
	return {
		name: config.name,
		description: config.description,
		url: config.website,
		telephone: config.phone,
		email: config.email,
		// The Turso column already stores schema.org-shaped keys; the builder
		// accepts both that and the platform's typed PostalAddress parts.
		address: (config.address as BusinessLdInput['address']) ?? null,
	}
}

export interface BlogPostingLdOptions {
	/** Canonical URL of this post — becomes `url` and `mainEntityOfPage`. */
	url?: string
	/** Site origin, for the breadcrumb trail's Home rung. */
	siteUrl?: string | null
	/** Label for the Home rung; defaults to the business name. */
	siteName?: string | null
}

/**
 * The BlogPosting node for one post. Unchanged in shape from the SDK's original
 * builder — additive only (`wordCount`, `keywords`), so existing pages keep
 * emitting exactly what they emitted before plus two fields Google reads.
 */
export function buildBlogPostingLd(
	post: BlogPost,
	author?: BlogAuthor,
	business?: BusinessConfig,
	options?: BlogPostingLdOptions,
): JsonLdObject {
	return buildArticleLd({
		headline: post.seoTitle ?? post.title,
		description: post.seoDesc,
		image: post.heroImageUrl,
		url: options?.url ?? null,
		datePublished: post.publishedAt,
		dateModified: post.updatedAt,
		inLanguage: post.language,
		keywords: post.keywords,
		body: post.content,
		...(author ? { author: { name: author.name, url: author.websiteUrl, image: author.avatarUrl } } : {}),
		...(business ? { publisher: toBusinessInput(business) } : {}),
	})
}

/**
 * EVERY node a hosted post page should carry: the BlogPosting, plus a FAQPage
 * when the body genuinely contains question headings with answers under them,
 * plus a BreadcrumbList when the canonical URL describes a hierarchy.
 *
 * This is what closes `missing_structured_data` for hosted posts across a whole
 * tenant at once: one SDK release, no per-page edits. The FAQ half is the part
 * that moves AI-Overview eligibility — but it only ever marks up Q&A the reader
 * can actually see, because fabricated FAQ markup earns a manual action.
 */
export function buildBlogPostingNodes(
	post: BlogPost,
	author?: BlogAuthor,
	business?: BusinessConfig,
	options?: BlogPostingLdOptions,
): JsonLdObject[] {
	const siteUrl = options?.siteUrl ?? business?.website ?? null
	const breadcrumbs: BreadcrumbItem[] = blogBreadcrumbs({
		siteName: options?.siteName ?? business?.name ?? null,
		siteUrl,
		postTitle: post.title,
		postUrl: options?.url ?? null,
	})

	return buildBlogPostingGraph({
		headline: post.seoTitle ?? post.title,
		description: post.seoDesc,
		image: post.heroImageUrl,
		url: options?.url ?? null,
		datePublished: post.publishedAt,
		dateModified: post.updatedAt,
		inLanguage: post.language,
		keywords: post.keywords,
		content: post.content,
		breadcrumbs,
		...(author ? { author: { name: author.name, url: author.websiteUrl, image: author.avatarUrl } } : {}),
		...(business ? { publisher: toBusinessInput(business) } : {}),
	})
}

/** The LocalBusiness node for a tenant's business config. Null without a name. */
export function buildLocalBusinessLd(config: BusinessConfig): JsonLdObject | null {
	return buildOrganizationLd({ ...toBusinessInput(config), localBusiness: true })
}

/** The Organization node — for a business with no single physical storefront. */
export function buildOrganizationLdFromConfig(config: BusinessConfig): JsonLdObject | null {
	return buildOrganizationLd(toBusinessInput(config))
}
