// Structural internal linking for the hosted blog: related articles, topic hub
// pages, and the "orphan post" check. Pure functions over stored post fields —
// no DB, no framework, browser-safe — so the SAME code decides three things
// that must never disagree:
//
//   • what the client site renders (sdk-server queries + sdk-client components),
//   • what the sitemap lists (the template's `buildTopicEntries`),
//   • what the seo-improvement loop counts as an inbound link when it decides a
//     post is an orphan (domain `loop-engine/pre-pass.ts` → `defects.ts`).
//
// WHY THIS EXISTS. The blog index listed posts chronologically with no
// categories, posts did not link to each other, and Search Console reported
// pages Google had never found. The seo-improvement loop treats internal links
// as an edit — one post at a time, at the model's discretion, inside a cooldown.
// A link graph that depends on a model remembering to add links is a link graph
// with holes. So the links are STRUCTURAL: every post gets a related-articles
// block and a place on one or more topic hubs, computed here from the keywords
// the blog-writing workflow already stores, and the loop only has to close the
// gap the structure cannot (a post whose keywords match nothing).
//
// Determinism is the contract. Every ranking below breaks ties on `createdAt`
// then `slug`, so a page rendered today and the loop's count tomorrow see the
// same three links. Nothing here calls a model.

import type { BlogContentIssue } from './blog-content-health'

/**
 * The first SDK release whose blog template renders the related-articles block
 * and the topic hubs. A tenant on an older SDK has NO structural links on its
 * live site, so the orphan check must count body links only for it — counting
 * links that are not there would hide every orphan the check exists to find.
 */
export const STRUCTURAL_LINKING_SDK_VERSION = '0.1.78'

/** The related-articles block shows at least this many posts when the blog has them. */
export const RELATED_ARTICLES_MIN = 3
/** …and never more than this many. Five is the ceiling a reader still scans. */
export const RELATED_ARTICLES_MAX = 5
/** A keyword becomes a topic hub once this many published posts share it. */
export const TOPIC_MIN_POSTS = 2
/** Below this many inbound hosted links a post is an orphan the loop must fix. */
export const ORPHAN_MIN_INBOUND_LINKS = 3
/** Site-relative mount point of the topic hubs. Locale prefix goes in front. */
export const BLOG_TOPIC_PATH = '/blog/topic'

/** The post fields the linking rules read. A subset of `BlogPost`, raw row or parsed. */
export interface LinkablePost {
	id: string
	slug: string
	title: string
	content: string
	language?: string | null
	/** Either the parsed `string[]` or the raw JSON text column — both are accepted. */
	keywords?: string[] | string | null
	createdAt?: Date | string | number | null
}

// ─── Keywords ────────────────────────────────────────────────────────────────

/** The stored keywords as a clean `string[]`, whatever shape they arrive in. */
export function parseKeywords(raw: unknown): string[] {
	let list: unknown = raw
	if (typeof raw === 'string') {
		const text = raw.trim()
		if (!text) return []
		try {
			list = JSON.parse(text)
		} catch {
			// Not JSON: treat as a comma-separated list, which is how a hand-typed
			// keywords field arrives from older portal forms.
			list = text.split(',')
		}
	}
	if (!Array.isArray(list)) return []
	const seen = new Set<string>()
	const out: string[] = []
	for (const item of list) {
		if (typeof item !== 'string') continue
		const k = item.trim()
		if (!k) continue
		const key = normalizeTopicKey(k)
		if (!key || seen.has(key)) continue
		seen.add(key)
		out.push(k)
	}
	return out
}

/**
 * The key two keywords are compared on: lowercased, punctuation dropped,
 * whitespace collapsed. "RSU Taxes", "rsu taxes" and "RSU-taxes" are one topic.
 */
export function normalizeTopicKey(keyword: string): string {
	return keyword
		.toLowerCase()
		.replace(/[^\p{L}\p{N}\s]+/gu, ' ')
		.replace(/\s+/g, ' ')
		.trim()
}

/** URL slug of a topic: the normalized key with hyphens. Empty when nothing survives. */
export function topicSlug(keyword: string): string {
	return normalizeTopicKey(keyword).replace(/\s+/g, '-')
}

// ─── Title tokens (second signal, after keywords) ────────────────────────────

// Function words in the two languages the template ships dictionaries for. A
// title match on "the" or "comment" is not a relationship.
const STOPWORDS = new Set([
	'the', 'a', 'an', 'and', 'or', 'of', 'to', 'in', 'for', 'on', 'with', 'your', 'you',
	'how', 'what', 'why', 'when', 'is', 'are', 'it', 'this', 'that', 'from', 'by', 'at',
	'as', 'can', 'do', 'does', 'should', 'guide', 'tips', 'vs', 'about', 'into', 'our',
	'de', 'la', 'le', 'les', 'des', 'du', 'et', 'un', 'une', 'pour', 'en', 'sur', 'vous',
	'votre', 'vos', 'comment', 'quoi', 'que', 'qui', 'est', 'sont', 'dans', 'avec', 'par',
])

function titleTokens(title: string): Set<string> {
	const out = new Set<string>()
	for (const raw of normalizeTopicKey(title).split(' ')) {
		if (raw.length < 3 || STOPWORDS.has(raw)) continue
		out.add(raw)
	}
	return out
}

// ─── Deterministic ordering ──────────────────────────────────────────────────

function createdAtMs(post: LinkablePost): number {
	const v = post.createdAt
	if (v == null) return 0
	if (v instanceof Date) return v.getTime()
	if (typeof v === 'number') return v
	const t = new Date(v).getTime()
	return Number.isFinite(t) ? t : 0
}

/** Newest first, then slug — the tie-break every ranking here falls back to. */
export function compareNewestFirst(a: LinkablePost, b: LinkablePost): number {
	const d = createdAtMs(b) - createdAtMs(a)
	if (d !== 0) return d
	return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0
}

function sameLanguage(a: LinkablePost, b: LinkablePost): boolean {
	return (a.language ?? 'en') === (b.language ?? 'en')
}

// ─── Related articles ────────────────────────────────────────────────────────

/** How much a shared keyword weighs against a shared title word. */
const KEYWORD_WEIGHT = 3
const TITLE_WEIGHT = 1

/**
 * Relatedness of two posts: shared keywords (weight 3) plus shared significant
 * title words (weight 1). Zero means "nothing in common"; the block then falls
 * back to recency so no post is ever left without links.
 */
export function relatedScore(a: LinkablePost, b: LinkablePost): number {
	const aKeys = new Set(parseKeywords(a.keywords).map(normalizeTopicKey))
	let shared = 0
	for (const k of parseKeywords(b.keywords)) if (aKeys.has(normalizeTopicKey(k))) shared += 1
	const aTitle = titleTokens(a.title)
	let words = 0
	for (const w of titleTokens(b.title)) if (aTitle.has(w)) words += 1
	return shared * KEYWORD_WEIGHT + words * TITLE_WEIGHT
}

export interface RankRelatedOptions {
	/** Never fewer than this when the blog has enough posts. Default `RELATED_ARTICLES_MIN`. */
	min?: number
	/** Never more than this. Default `RELATED_ARTICLES_MAX`. */
	max?: number
}

/**
 * The related-articles list for `current`: same language, never itself,
 * scored posts first (best first, newest first on ties), then the newest
 * unrelated posts until the block has `min` entries. Deterministic — the same
 * corpus always yields the same list, which is what lets the loop count these
 * as inbound links without rendering the page.
 */
export function rankRelatedPosts<T extends LinkablePost>(
	current: LinkablePost,
	candidates: readonly T[],
	opts: RankRelatedOptions = {},
): T[] {
	const min = Math.max(0, opts.min ?? RELATED_ARTICLES_MIN)
	const max = Math.max(min, opts.max ?? RELATED_ARTICLES_MAX)
	const pool = candidates.filter(
		(p) => p.id !== current.id && p.slug !== current.slug && sameLanguage(current, p),
	)
	const scored = pool
		.map((post) => ({ post, score: relatedScore(current, post) }))
		.sort((x, y) => y.score - x.score || compareNewestFirst(x.post, y.post))

	const picked: T[] = []
	for (const { post, score } of scored) {
		if (picked.length >= max) break
		if (score <= 0) break
		picked.push(post)
	}
	if (picked.length < min) {
		const chosen = new Set(picked.map((p) => p.id))
		for (const { post } of scored) {
			if (picked.length >= min) break
			if (chosen.has(post.id)) continue
			picked.push(post)
		}
	}
	return picked
}

// ─── Topic hubs ──────────────────────────────────────────────────────────────

export interface BlogTopic {
	/** URL segment under `BLOG_TOPIC_PATH`. */
	slug: string
	/** Display form: the most common casing the posts themselves used. */
	label: string
	/** Newest first. */
	postSlugs: string[]
	postCount: number
}

/**
 * Every keyword shared by at least `TOPIC_MIN_POSTS` posts, as a hub. One
 * language at a time — pass the posts of one locale. Hubs are ordered largest
 * first, then by slug, so the index page's chip row is stable across builds.
 */
export function buildBlogTopics(posts: readonly LinkablePost[]): BlogTopic[] {
	const bySlug = new Map<string, { labels: Map<string, number>; posts: Map<string, LinkablePost> }>()
	for (const post of posts) {
		for (const keyword of parseKeywords(post.keywords)) {
			const slug = topicSlug(keyword)
			if (!slug) continue
			let entry = bySlug.get(slug)
			if (!entry) {
				entry = { labels: new Map(), posts: new Map() }
				bySlug.set(slug, entry)
			}
			entry.labels.set(keyword, (entry.labels.get(keyword) ?? 0) + 1)
			entry.posts.set(post.slug, post)
		}
	}

	const topics: BlogTopic[] = []
	for (const [slug, entry] of bySlug) {
		if (entry.posts.size < TOPIC_MIN_POSTS) continue
		const label = [...entry.labels.entries()].sort(
			(a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1),
		)[0]![0]
		const ordered = [...entry.posts.values()].sort(compareNewestFirst).map((p) => p.slug)
		topics.push({ slug, label, postSlugs: ordered, postCount: ordered.length })
	}
	return topics.sort((a, b) => b.postCount - a.postCount || (a.slug < b.slug ? -1 : 1))
}

/** The hubs this post sits on, in hub order. */
export function topicsForPost(post: Pick<LinkablePost, 'slug'>, topics: readonly BlogTopic[]): BlogTopic[] {
	return topics.filter((t) => t.postSlugs.includes(post.slug))
}

// ─── Body links ──────────────────────────────────────────────────────────────

// `/blog/<slug>` with an optional locale segment in front, on any host: a post
// that links to `https://www.example.com/en/blog/x` is linking to hosted post
// `x`. Absolute-or-relative is decided by whether the slug matches a post the
// caller hosts, never by the hostname, which this module does not know.
const BLOG_PATH = /^\/(?:[a-z]{2}(?:-[a-z]{2})?\/)?blog\/([^/?#]+)\/?$/i
const MARKDOWN_LINK = /\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g
const HTML_HREF = /href\s*=\s*["']([^"']+)["']/gi

function pathOf(url: string): string | null {
	try {
		if (/^https?:\/\//i.test(url)) return new URL(url).pathname
		if (url.startsWith('/')) return url.split(/[?#]/)[0] ?? null
		return null
	} catch {
		return null
	}
}

/**
 * Slugs of every hosted blog post the markdown links to (lowercased, deduped).
 * Reads both markdown links and raw `<a href>` tags, since imported posts
 * carry HTML bodies.
 */
export function extractHostedLinkSlugs(markdown: string): Set<string> {
	const slugs = new Set<string>()
	const consider = (raw: string) => {
		const path = pathOf(raw.trim())
		if (!path) return
		const m = BLOG_PATH.exec(path)
		if (!m?.[1]) return
		let slug = m[1]
		try {
			slug = decodeURIComponent(slug)
		} catch {
			// keep raw
		}
		slugs.add(slug.toLowerCase())
	}
	for (const m of markdown.matchAll(MARKDOWN_LINK)) if (m[1]) consider(m[1])
	for (const m of markdown.matchAll(HTML_HREF)) if (m[1]) consider(m[1])
	return slugs
}

// ─── Inbound links + the orphan check ────────────────────────────────────────

export interface InboundLinkReport {
	/** Slugs of posts whose BODY links here. Counts on every site, whatever SDK it runs. */
	bodyFrom: string[]
	/** Slugs of posts whose related-articles block lists this post. Structural. */
	relatedFrom: string[]
	/** Topic hubs that list this post. Structural — one inbound link per hub page. */
	topicHubs: string[]
	/** Distinct inbound hosted links, as the check counts them. */
	total: number
}

export interface InboundLinkOptions {
	/**
	 * Count the related block and the hubs. TRUE only when the live site renders
	 * them (SDK ≥ `STRUCTURAL_LINKING_SDK_VERSION`); otherwise they do not exist
	 * on the site Google crawls and counting them would hide real orphans.
	 */
	includeStructural: boolean
}

/**
 * Inbound hosted links per post, keyed by post id. Related blocks and hubs are
 * computed per language, exactly as the site renders them; body links count
 * across the whole corpus, since a translation may link to the original.
 */
export function computeInboundLinks(
	posts: readonly LinkablePost[],
	opts: InboundLinkOptions,
): Map<string, InboundLinkReport> {
	const reports = new Map<string, InboundLinkReport>()
	const bySlug = new Map<string, LinkablePost>()
	for (const post of posts) {
		bySlug.set(post.slug.toLowerCase(), post)
		reports.set(post.id, { bodyFrom: [], relatedFrom: [], topicHubs: [], total: 0 })
	}

	for (const source of posts) {
		for (const slug of extractHostedLinkSlugs(source.content)) {
			const target = bySlug.get(slug)
			if (!target || target.id === source.id) continue
			reports.get(target.id)!.bodyFrom.push(source.slug)
		}
	}

	if (opts.includeStructural) {
		const byLanguage = new Map<string, LinkablePost[]>()
		for (const post of posts) {
			const lang = post.language ?? 'en'
			const list = byLanguage.get(lang)
			if (list) list.push(post)
			else byLanguage.set(lang, [post])
		}
		for (const corpus of byLanguage.values()) {
			for (const source of corpus) {
				for (const target of rankRelatedPosts(source, corpus)) {
					reports.get(target.id)!.relatedFrom.push(source.slug)
				}
			}
			const topics = buildBlogTopics(corpus)
			for (const topic of topics) {
				for (const slug of topic.postSlugs) {
					const post = bySlug.get(slug.toLowerCase())
					if (post) reports.get(post.id)!.topicHubs.push(topic.slug)
				}
			}
		}
	}

	for (const report of reports.values()) {
		report.bodyFrom.sort()
		report.relatedFrom.sort()
		report.topicHubs.sort()
		report.total =
			new Set([...report.bodyFrom, ...report.relatedFrom]).size + report.topicHubs.length
	}
	return reports
}

export interface OrphanPostFinding<T extends LinkablePost = LinkablePost> {
	post: T
	inbound: InboundLinkReport
	issue: BlogContentIssue
	/**
	 * The posts that SHOULD link here and do not: the orphan's closest related
	 * posts whose body has no link to it, best match first. This is the fix,
	 * named — an edit to each of these, not to the orphan.
	 */
	suggestedSources: T[]
	/** Echo of `opts.includeStructural`: whether the related block and hubs were counted. */
	structuralCounted: boolean
}

/** How many source posts an orphan finding names. Enough to clear the threshold. */
const SUGGESTED_SOURCES = ORPHAN_MIN_INBOUND_LINKS

/**
 * Every post with fewer than `ORPHAN_MIN_INBOUND_LINKS` inbound hosted links,
 * with the posts that should link to it. Deterministic, corpus-level — this is
 * the check `checkBlogPostContent` cannot make from one post's own fields.
 */
export function checkOrphanPosts<T extends LinkablePost>(
	posts: readonly T[],
	opts: InboundLinkOptions,
): OrphanPostFinding<T>[] {
	if (posts.length < 2) return []
	const reports = computeInboundLinks(posts, opts)
	const findings: OrphanPostFinding<T>[] = []

	for (const post of posts) {
		const inbound = reports.get(post.id)
		if (!inbound || inbound.total >= ORPHAN_MIN_INBOUND_LINKS) continue
		const linkingSlugs = new Set(inbound.bodyFrom)
		const suggestedSources = rankRelatedPosts(post, posts, {
			min: SUGGESTED_SOURCES,
			max: SUGGESTED_SOURCES * 2,
		})
			.filter((p) => !linkingSlugs.has(p.slug))
			.slice(0, SUGGESTED_SOURCES)

		const structuralNote = opts.includeStructural
			? ''
			: ' (body links only: this site runs an SDK without the related-articles block and topic hubs)'
		findings.push({
			post,
			inbound,
			suggestedSources,
			structuralCounted: opts.includeStructural,
			issue: {
				id: 'orphan_post',
				severity: inbound.total === 0 ? 'error' : 'warn',
				message: `Only ${inbound.total} inbound hosted link(s) point at /blog/${post.slug} (needs ${ORPHAN_MIN_INBOUND_LINKS})${structuralNote}`,
				fix:
					suggestedSources.length > 0
						? `Add a contextual link to /blog/${post.slug} from ${suggestedSources
								.map((p) => `/blog/${p.slug}`)
								.join(', ')}`
						: `Add contextual links to /blog/${post.slug} from related posts you host`,
			},
		})
	}
	return findings.sort((a, b) => a.inbound.total - b.inbound.total || compareNewestFirst(a.post, b.post))
}

// ─── Portal / tool summary ───────────────────────────────────────────────────

/** A post an orphan should be linked from — enough to name it and open it. */
export interface OrphanLinkSource {
	id: string
	slug: string
	title: string
}

/**
 * The browser-safe, serialisable form of an `OrphanPostFinding`: what the
 * portal's health chip and SEO panel render, and what the Operator tool
 * returns. Carries the finding's fix by name (the posts to link from) so a
 * surface can never show the number without the "what to do".
 */
export interface BlogOrphanSummary {
	issue: BlogContentIssue
	/** Distinct inbound hosted links the check counted. */
	inboundLinks: number
	/** The threshold: `ORPHAN_MIN_INBOUND_LINKS`. */
	needed: number
	/** Whether the related block and topic hubs were counted (SDK renders them). */
	structuralCounted: boolean
	/** The posts that should link here and do not, best match first. */
	linkFrom: OrphanLinkSource[]
}

export function summarizeOrphanFinding(finding: OrphanPostFinding): BlogOrphanSummary {
	return {
		issue: finding.issue,
		inboundLinks: finding.inbound.total,
		needed: ORPHAN_MIN_INBOUND_LINKS,
		structuralCounted: finding.structuralCounted,
		linkFrom: finding.suggestedSources.map((p) => ({ id: p.id, slug: p.slug, title: p.title })),
	}
}

/**
 * `checkOrphanPosts` keyed by post id, already summarised — the shape a list
 * endpoint attaches to each row. Pass the PUBLISHED corpus: a draft is not on
 * the site, so it neither links nor is linked to.
 */
export function orphanSummariesById(
	posts: readonly LinkablePost[],
	opts: InboundLinkOptions,
): Map<string, BlogOrphanSummary> {
	const out = new Map<string, BlogOrphanSummary>()
	for (const finding of checkOrphanPosts(posts, opts)) {
		out.set(finding.post.id, summarizeOrphanFinding(finding))
	}
	return out
}

// ─── SDK version gate ────────────────────────────────────────────────────────

function semverParts(v: string): number[] | null {
	const m = /^v?(\d+)\.(\d+)\.(\d+)/.exec(v.trim())
	if (!m) return null
	return [Number(m[1]), Number(m[2]), Number(m[3])]
}

/**
 * Does a site on `sdkVersion` render the structural links? `unknown` (the
 * onboarding default) or unparseable → false, the conservative answer.
 */
export function sdkRendersStructuralLinks(sdkVersion: string | null | undefined): boolean {
	if (!sdkVersion) return false
	const have = semverParts(sdkVersion)
	const need = semverParts(STRUCTURAL_LINKING_SDK_VERSION)
	if (!have || !need) return false
	for (let i = 0; i < 3; i += 1) {
		const a = have[i] ?? 0
		const b = need[i] ?? 0
		if (a !== b) return a > b
	}
	return true
}
