// ─── schema.org JSON-LD builders (browser-safe, pure) ────────────────────────
//
// The site crawl flags `missing_structured_data` on every page with no
// schema.org markup and recommends "Add JSON-LD (Organization, Article,
// BreadcrumbList, FAQ as appropriate)". Nothing could act on that: the only
// builder in the codebase lived in `sdk-client/src/seo/json-ld.ts`, which the
// platform cannot import (browser package, React components, no server entry),
// so the recommendation dead-ended on the owner.
//
// This module is that builder, moved to the one place BOTH sides can reach:
//
//   • `sdk-client` renders it into pages this engine hosts — fixing every blog
//     post at once through an SDK release rather than per-page edits.
//   • `domain` renders the SAME objects to a `<script>` string the site-health
//     loop pastes into a change brief for pages we do NOT host.
//
// One builder, two consumers, is the whole point. A separate snippet generator
// for briefs would drift from what the SDK actually emits, and the owner would
// be pasting markup that no longer matches their hosted pages.
//
// LIVES IN `types`, NOT `domain`, FOR THE REASON site-crawl-fixability.ts
// documents: `sdk-client` bundles `@growth-engine/types` (tsup `noExternal`)
// and its portal consumers are `'use client'`. A value-import that reaches into
// `domain` drags `mongodb` into a browser bundle — a next build failure that
// typecheck does not catch. Everything here is pure: no I/O, no framework, no
// Node built-ins.

// ─── Core types ──────────────────────────────────────────────────────────────

export type JsonLdObject = Record<string, unknown>

/** A question/answer pair harvested from a post body, for FAQPage markup. */
export interface FaqPair {
	question: string
	answer: string
}

/** One rung of a BreadcrumbList, in order from the site root to this page. */
export interface BreadcrumbItem {
	name: string
	/** Absolute URL. The LAST crumb may omit it (schema.org allows the leaf bare). */
	url?: string
}

/**
 * The business facts an Organization / LocalBusiness node is built from.
 *
 * Deliberately a narrow structural type rather than `BusinessConfig` or
 * `BusinessConfigRecord`: the SDK reads the Turso `BusinessConfig` row (address
 * is an object) while the platform reads the Mongo `BusinessConfigRecord`
 * (address is a string) plus `tenant.postalAddress` (five typed parts). All
 * three describe the same business. Accepting the union here means neither side
 * has to reshape its data before asking for markup.
 */
export interface BusinessLdInput {
	name?: string | null | undefined
	description?: string | null | undefined
	url?: string | null | undefined
	telephone?: string | null | undefined
	email?: string | null | undefined
	logo?: string | null | undefined
	/** Free-text line, or typed parts. A string is emitted as `streetAddress`. */
	address?: string | PostalAddressLdInput | null | undefined
	/** Profile URLs that identify the same business (GBP, Yelp, Facebook, LinkedIn…). */
	sameAs?: (string | null | undefined)[] | null | undefined
	/**
	 * When true the node is typed `LocalBusiness` instead of `Organization`.
	 * A LocalBusiness that carries no address is worse than an Organization —
	 * it promises a place and names none — so this is a caller's decision, made
	 * from whether the business actually has a storefront.
	 */
	localBusiness?: boolean | undefined
}

export interface PostalAddressLdInput {
	street?: string | null | undefined
	street2?: string | null | undefined
	city?: string | null | undefined
	region?: string | null | undefined
	postalCode?: string | null | undefined
	country?: string | null | undefined
	// ── Already-schema.org-shaped keys ──
	// The SDK reads the Turso `business_config.address` column, which stores the
	// PostalAddress fields under their schema.org names and was spread verbatim
	// into the node before this module existed. Accepting them here keeps that
	// behaviour byte-identical instead of silently dropping every SDK address.
	streetAddress?: string | null | undefined
	addressLocality?: string | null | undefined
	addressRegion?: string | null | undefined
	addressCountry?: string | null | undefined
}

/** The article facts a BlogPosting / Article node is built from. */
export interface ArticleLdInput {
	headline?: string | null | undefined
	description?: string | null | undefined
	image?: string | null | undefined
	/** Canonical URL of the article. Also becomes `mainEntityOfPage`. */
	url?: string | null | undefined
	datePublished?: Date | string | null | undefined
	dateModified?: Date | string | null | undefined
	inLanguage?: string | null | undefined
	keywords?: string[] | null | undefined
	/** Body text or markdown — used for `wordCount` only, never emitted. */
	body?: string | null | undefined
	author?: { name?: string | null; url?: string | null; image?: string | null } | null | undefined
	publisher?: BusinessLdInput | null | undefined
	/** `Article` is the safer default for a non-blog page (a service page, a guide). */
	type?: 'BlogPosting' | 'Article' | 'NewsArticle' | undefined
}

// ─── Small pure helpers ──────────────────────────────────────────────────────

function omitEmpty(obj: Record<string, unknown>): Record<string, unknown> {
	const out: Record<string, unknown> = {}
	for (const [key, value] of Object.entries(obj)) {
		if (value == null) continue
		if (typeof value === 'string' && value.trim() === '') continue
		if (Array.isArray(value) && value.length === 0) continue
		out[key] = value
	}
	return out
}

/** ISO-8601 or null. Accepts what both a Turso row (Date) and Mongo (string) hold. */
function isoDate(value: Date | string | null | undefined): string | null {
	if (value == null) return null
	const d = value instanceof Date ? value : new Date(value)
	if (Number.isNaN(d.getTime())) return null
	return d.toISOString()
}

/**
 * Words in a body, for `wordCount`. Each CJK character counts as a word, for the
 * reason `blog-content-health.ts` documents: a whitespace split scores a whole
 * Chinese article as a few dozen words.
 */
const CJK_CHAR =
	/[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\uff66-\uff9f\uac00-\ud7af]/

export function countLdWords(text: string): number {
	let cjk = 0
	let plain = ''
	for (const ch of text) {
		if (CJK_CHAR.test(ch)) cjk += 1
		else plain += ch
	}
	const latin = plain.trim() === '' ? 0 : plain.trim().split(/\s+/).length
	return cjk + latin
}

/** Strip markdown decoration so an answer reads as prose inside JSON-LD. */
export function stripMarkdown(md: string): string {
	return md
		.replace(/```[\s\S]*?```/g, ' ')
		.replace(/`([^`]*)`/g, '$1')
		.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
		.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
		.replace(/^\s{0,3}>\s?/gm, '')
		.replace(/^\s{0,3}[-*+]\s+/gm, '')
		.replace(/^\s{0,3}\d+\.\s+/gm, '')
		.replace(/\*\*([^*]+)\*\*/g, '$1')
		.replace(/\*([^*]+)\*/g, '$1')
		.replace(/__([^_]+)__/g, '$1')
		.replace(/<[^>]+>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
}

// ─── FAQ extraction ──────────────────────────────────────────────────────────
//
// Google requires FAQPage markup to reflect question/answer content VISIBLE on
// the page. Inventing Q&A pairs, or marking up a heading that is not a question,
// is a structured-data violation that can earn a manual action — so the
// detection here is deliberately conservative and refuses more than it accepts.

/** A heading is a question when it ends in `?` or opens with an interrogative. */
const INTERROGATIVE_OPENERS =
	/^(how|what|why|when|where|who|whom|whose|which|can|could|should|shall|do|does|did|is|are|was|were|will|would|may|might|must|am)\b/i

/** Enough of an answer to be worth marking up; below this it is a stub. */
const MIN_ANSWER_CHARS = 40
/** Google truncates long answers; past this we are padding, not answering. */
const MAX_ANSWER_CHARS = 1200
/** Below this many pairs a page is not an FAQ, it just has one question in it. */
export const MIN_FAQ_PAIRS = 2
/** Guard against a headings-only outline page turning into 60 empty entries. */
export const MAX_FAQ_PAIRS = 20

export function isQuestionHeading(text: string): boolean {
	const t = text.trim()
	if (t.length < 8 || t.length > 200) return false
	if (t.endsWith('?') || t.endsWith('\uff1f')) return true
	return INTERROGATIVE_OPENERS.test(t)
}

/**
 * PURE. Harvest FAQ pairs from a markdown body: every `##`/`###` heading that
 * reads as a question, paired with the prose beneath it up to the next heading
 * of the same or higher level.
 *
 * Returns `[]` for anything that is not clearly an FAQ. That is the safe answer:
 * a missing FAQPage node costs a rich result, a fabricated one costs the domain.
 */
export function extractFaqPairs(markdown: string): FaqPair[] {
	if (!markdown) return []
	const lines = markdown.split(/\r?\n/)
	const pairs: FaqPair[] = []

	let current: { question: string; level: number; body: string[] } | null = null
	let inFence = false

	const flush = () => {
		if (!current) return
		const answer = stripMarkdown(current.body.join('\n'))
		if (answer.length >= MIN_ANSWER_CHARS) {
			pairs.push({
				question: current.question,
				answer: answer.length > MAX_ANSWER_CHARS
					? `${answer.slice(0, MAX_ANSWER_CHARS).replace(/\s+\S*$/, '')}…`
					: answer,
			})
		}
		current = null
	}

	for (const line of lines) {
		if (/^\s{0,3}```/.test(line)) {
			inFence = !inFence
			if (current) current.body.push(line)
			continue
		}
		if (inFence) {
			if (current) current.body.push(line)
			continue
		}

		const heading = /^\s{0,3}(#{2,4})\s+(.+?)\s*#*\s*$/.exec(line)
		if (heading) {
			const level = heading[1]!.length
			const text = stripMarkdown(heading[2]!)
			// A same-or-higher-level heading closes the open answer either way;
			// only a question opens a new one.
			if (current && level <= current.level) flush()
			if (isQuestionHeading(text)) {
				current = { question: text, level, body: [] }
			}
			continue
		}
		if (current) current.body.push(line)
	}
	flush()

	return pairs.length >= MIN_FAQ_PAIRS ? pairs.slice(0, MAX_FAQ_PAIRS) : []
}

/**
 * PURE. The HTML counterpart of {@link extractFaqPairs}, for pages this engine
 * does NOT host — the site-health loop reads the customer's own rendered HTML,
 * not markdown, when it writes a change brief.
 *
 * Same conservatism, same floor: only `<h2>`–`<h4>` headings that read as
 * questions, only when the prose beneath them is substantial, and only when the
 * page carries at least {@link MIN_FAQ_PAIRS}. `<script>`/`<style>` content is
 * dropped first so a JSON blob or a CSS rule can never become an "answer".
 */
export function extractFaqPairsFromHtml(html: string): FaqPair[] {
	if (!html) return []
	const cleaned = html
		.replace(/<script[\s\S]*?<\/script>/gi, ' ')
		.replace(/<style[\s\S]*?<\/style>/gi, ' ')
		.replace(/<!--[\s\S]*?-->/g, ' ')

	// Split on h2/h3/h4 boundaries, keeping the level and text of each heading.
	const headingRe = /<h([234])\b[^>]*>([\s\S]*?)<\/h\1\s*>/gi
	const sections: Array<{ level: number; question: string; start: number }> = []
	let match: RegExpExecArray | null
	while ((match = headingRe.exec(cleaned)) !== null) {
		sections.push({
			level: Number(match[1]),
			question: stripMarkdown(match[2]!),
			start: match.index + match[0].length,
		})
	}

	const pairs: FaqPair[] = []
	for (let i = 0; i < sections.length; i++) {
		const section = sections[i]!
		if (!isQuestionHeading(section.question)) continue
		// The answer runs to the next heading at the same or a higher level.
		let end = cleaned.length
		for (let j = i + 1; j < sections.length; j++) {
			const next = sections[j]!
			if (next.level <= section.level) {
				// Rewind past the next heading's own markup.
				end = cleaned.lastIndexOf('<h', next.start)
				break
			}
		}
		const answer = stripMarkdown(cleaned.slice(section.start, Math.max(end, section.start)))
		if (answer.length < MIN_ANSWER_CHARS) continue
		pairs.push({
			question: section.question,
			answer:
				answer.length > MAX_ANSWER_CHARS
					? `${answer.slice(0, MAX_ANSWER_CHARS).replace(/\s+\S*$/, '')}\u2026`
					: answer,
		})
	}

	return pairs.length >= MIN_FAQ_PAIRS ? pairs.slice(0, MAX_FAQ_PAIRS) : []
}

// ─── Node builders ───────────────────────────────────────────────────────────

const CONTEXT = 'https://schema.org'

export function buildPostalAddressLd(
	address: string | PostalAddressLdInput | null | undefined,
): JsonLdObject | null {
	if (!address) return null
	if (typeof address === 'string') {
		const trimmed = address.trim()
		if (!trimmed) return null
		return { '@type': 'PostalAddress', streetAddress: trimmed }
	}
	const street = [address.street, address.street2].filter((p) => p && p.trim()).join(', ')
	const node = omitEmpty({
		'@type': 'PostalAddress',
		streetAddress: street || address.streetAddress || null,
		addressLocality: address.city ?? address.addressLocality ?? null,
		addressRegion: address.region ?? address.addressRegion ?? null,
		postalCode: address.postalCode ?? null,
		addressCountry: address.country ?? address.addressCountry ?? null,
	})
	// `@type` alone is not an address.
	return Object.keys(node).length > 1 ? node : null
}

/**
 * PURE. An Organization (or LocalBusiness) node. Returns null without a name —
 * a node with no `name` identifies nothing and is worse than no markup at all.
 */
export function buildOrganizationLd(business: BusinessLdInput): JsonLdObject | null {
	const name = business.name?.trim()
	if (!name) return null

	const sameAs = (business.sameAs ?? [])
		.filter((u): u is string => typeof u === 'string' && u.trim() !== '')
		.map((u) => u.trim())

	const node: JsonLdObject = {
		'@context': CONTEXT,
		'@type': business.localBusiness ? 'LocalBusiness' : 'Organization',
		...omitEmpty({
			name,
			description: business.description ?? null,
			url: business.url ?? null,
			telephone: business.telephone ?? null,
			email: business.email ?? null,
			logo: business.logo ?? null,
			sameAs: sameAs.length > 0 ? Array.from(new Set(sameAs)) : null,
		}),
	}

	const address = buildPostalAddressLd(business.address)
	if (address) node.address = address
	return node
}

/** Back-compat alias: the SDK's original name for the LocalBusiness builder. */
export function buildLocalBusinessLd(business: BusinessLdInput): JsonLdObject | null {
	return buildOrganizationLd({ ...business, localBusiness: true })
}

/**
 * PURE. A BlogPosting / Article node. `publisher` and `author` are nested nodes
 * (no `@context` of their own — only the root node carries it).
 */
export function buildArticleLd(article: ArticleLdInput): JsonLdObject {
	const node: JsonLdObject = {
		'@context': CONTEXT,
		'@type': article.type ?? 'BlogPosting',
		...omitEmpty({
			headline: article.headline ?? null,
			description: article.description ?? null,
			image: article.image ?? null,
			url: article.url ?? null,
			datePublished: isoDate(article.datePublished),
			dateModified: isoDate(article.dateModified) ?? isoDate(article.datePublished),
			inLanguage: article.inLanguage ?? null,
			keywords: article.keywords && article.keywords.length > 0 ? article.keywords.join(', ') : null,
		}),
	}

	if (article.url) {
		node.mainEntityOfPage = { '@type': 'WebPage', '@id': article.url }
	}

	if (article.body) {
		const words = countLdWords(stripMarkdown(article.body))
		if (words > 0) node.wordCount = words
	}

	if (article.author?.name) {
		node.author = omitEmpty({
			'@type': 'Person',
			name: article.author.name,
			url: article.author.url ?? null,
			image: article.author.image ?? null,
		})
	}

	if (article.publisher?.name) {
		// IDENTITY FIELDS ONLY. A publisher node exists to say who published the
		// article; Google reads `name` and `logo` off it and nothing else. Copying
		// the business's address, phone and opening hours onto every article both
		// bloats each page and duplicates the Organization/LocalBusiness node the
		// site already emits once at layout level — where that data belongs.
		node.publisher = omitEmpty({
			'@type': 'Organization',
			name: article.publisher.name.trim(),
			url: article.publisher.url ?? null,
			logo: article.publisher.logo ?? null,
		})
	}

	return node
}

/**
 * PURE. A FAQPage node, or null when there is nothing legitimate to mark up.
 * Never fabricates: callers pass pairs that came off the rendered page.
 */
export function buildFaqPageLd(pairs: FaqPair[]): JsonLdObject | null {
	const usable = pairs.filter((p) => p.question.trim() && p.answer.trim())
	if (usable.length < MIN_FAQ_PAIRS) return null
	return {
		'@context': CONTEXT,
		'@type': 'FAQPage',
		mainEntity: usable.slice(0, MAX_FAQ_PAIRS).map((p) => ({
			'@type': 'Question',
			name: p.question.trim(),
			acceptedAnswer: { '@type': 'Answer', text: p.answer.trim() },
		})),
	}
}

/**
 * PURE. A BreadcrumbList node. Returns null below two rungs: a breadcrumb trail
 * with one entry describes no hierarchy and earns no breadcrumb rich result.
 */
export function buildBreadcrumbListLd(items: BreadcrumbItem[]): JsonLdObject | null {
	const usable = items.filter((i) => i.name.trim())
	if (usable.length < 2) return null
	return {
		'@context': CONTEXT,
		'@type': 'BreadcrumbList',
		itemListElement: usable.map((item, index) => ({
			'@type': 'ListItem',
			position: index + 1,
			name: item.name.trim(),
			...(item.url ? { item: item.url } : {}),
		})),
	}
}

/** PURE. A WebSite node — lets search engines attribute a site name. */
export function buildWebSiteLd(input: {
	name?: string | null | undefined
	url?: string | null | undefined
}): JsonLdObject | null {
	const name = input.name?.trim()
	const url = input.url?.trim()
	if (!name || !url) return null
	return { '@context': CONTEXT, '@type': 'WebSite', name, url }
}

// ─── Page-level assembly ─────────────────────────────────────────────────────

export interface BlogPostingGraphInput extends ArticleLdInput {
	/** Markdown body — mined for FAQ pairs. Pass the SAME text the page renders. */
	content?: string | null | undefined
	/** Pre-extracted pairs. Overrides mining `content`, for callers reading HTML. */
	faqPairs?: FaqPair[] | null | undefined
	/** Breadcrumb trail, root-first. Below two rungs it is dropped. */
	breadcrumbs?: BreadcrumbItem[] | null | undefined
}

/**
 * PURE. Every node a hosted blog-post page should emit, in one array: the
 * Article, plus FAQPage and BreadcrumbList when the page legitimately supports
 * them. Each is a separate top-level node with its own `@context` — the shape
 * Google's Rich Results Test expects and the shape `renderJsonLdScriptTag`
 * emits as one script.
 */
export function buildBlogPostingGraph(input: BlogPostingGraphInput): JsonLdObject[] {
	const nodes: JsonLdObject[] = [
		buildArticleLd({ ...input, body: input.body ?? input.content ?? null }),
	]

	const pairs = input.faqPairs ?? (input.content ? extractFaqPairs(input.content) : [])
	const faq = buildFaqPageLd(pairs)
	if (faq) nodes.push(faq)

	const crumbs = buildBreadcrumbListLd(input.breadcrumbs ?? [])
	if (crumbs) nodes.push(crumbs)

	return nodes
}

/**
 * PURE. The breadcrumb trail for a blog post, derived from its canonical URL.
 * Home → Blog → post title. Returns `[]` when the URL cannot be parsed, so a
 * manual design (or a bad `website` value) never throws here.
 */
export function blogBreadcrumbs(options: {
	siteName?: string | null | undefined
	siteUrl?: string | null | undefined
	blogLabel?: string | undefined
	postTitle?: string | null | undefined
	postUrl?: string | null | undefined
}): BreadcrumbItem[] {
	const { siteName, siteUrl, postTitle, postUrl } = options
	if (!siteUrl || !postTitle) return []
	let origin: string
	let blogUrl: string
	try {
		const parsed = new URL(siteUrl)
		origin = parsed.origin
		// The blog index is the post URL minus its last segment when we have one,
		// so a site serving posts at /articles/x does not get a wrong /blog crumb.
		if (postUrl) {
			const p = new URL(postUrl)
			const segments = p.pathname.split('/').filter(Boolean)
			segments.pop()
			blogUrl = `${p.origin}/${segments.join('/')}`.replace(/\/+$/, '') || p.origin
		} else {
			blogUrl = `${origin}/blog`
		}
	} catch {
		return []
	}
	if (blogUrl === origin) {
		return [
			{ name: siteName?.trim() || 'Home', url: origin },
			{ name: postTitle.trim(), ...(postUrl ? { url: postUrl } : {}) },
		]
	}
	return [
		{ name: siteName?.trim() || 'Home', url: origin },
		{ name: options.blogLabel ?? 'Blog', url: blogUrl },
		{ name: postTitle.trim(), ...(postUrl ? { url: postUrl } : {}) },
	]
}

// ─── Serialization ───────────────────────────────────────────────────────────

/**
 * Serialize for embedding inside `<script type="application/ld+json">`.
 *
 * The `<` escape is NOT cosmetic. JSON-LD goes into the page as raw text, and a
 * post body containing `</script>` — a legitimate thing for an article about
 * HTML to contain — would otherwise close the tag early and inject the rest of
 * the JSON into the document as markup. `\u003c` is valid JSON, parses back to
 * `<`, and cannot terminate a tag. U+2028/U+2029 are escaped for the same
 * reason: they are valid JSON but illegal raw in a JavaScript string.
 */
export function serializeJsonLd(data: JsonLdObject | JsonLdObject[], pretty = false): string {
	const payload = Array.isArray(data) && data.length === 1 ? data[0]! : data
	return JSON.stringify(payload, null, pretty ? 2 : 0)
		.replace(/</g, '\\u003c')
		.replace(/>/g, '\\u003e')
		.replace(/&/g, '\\u0026')
		.replace(/\u2028/g, '\\u2028')
		.replace(/\u2029/g, '\\u2029')
}

/**
 * The complete `<script>` element as text — what a change brief hands a
 * developer to paste into a page this engine does not host. Byte-identical in
 * content to what the SDK renders on hosted pages, because it comes from the
 * same builders.
 */
export function renderJsonLdScriptTag(data: JsonLdObject | JsonLdObject[], pretty = true): string {
	return `<script type="application/ld+json">\n${serializeJsonLd(data, pretty)}\n</script>`
}
