'use client'

import { useState, useEffect } from 'react'
import { sdkFetch } from '../client'

interface UseVariablesResult {
	/** Flat `key → value` map. Company-scope only; user-scope values are never served. */
	variables: Record<string, string>
	loading: boolean
	error: string | null
}

/**
 * Tenant-wide variables (phone numbers, booking URLs, price points) as a flat
 * key/value map. The route only ever returns company-scope rows, so nothing
 * here is user-specific.
 */
export function useVariables(): UseVariablesResult {
	const [variables, setVariables] = useState<Record<string, string>>({})
	const [loading, setLoading] = useState(true)
	const [error, setError] = useState<string | null>(null)

	useEffect(() => {
		let cancelled = false

		async function load() {
			setLoading(true)
			const res = await sdkFetch<{ variables: Record<string, string> }>('/variables')
			if (cancelled) return
			if (res.error) {
				setError(res.error)
			} else {
				setError(null)
				setVariables(res.data?.variables ?? {})
			}
			setLoading(false)
		}

		void load()
		return () => {
			cancelled = true
		}
	}, [])

	return { variables, loading, error }
}
