import type { BusinessConfig } from '@growth-engine/types'
import { buildLocalBusinessLd, buildOrganizationLdFromConfig } from './json-ld'
import { JsonLd } from './JsonLd'

export interface BusinessJsonLdProps {
	config: BusinessConfig
	/**
	 * Emit `Organization` instead of `LocalBusiness`. Use it when the business has
	 * no single address customers visit — an online-only shop, a distributed
	 * agency. A `LocalBusiness` node that names no place promises a storefront the
	 * page cannot back up, which is worse markup than the plainer Organization.
	 */
	organization?: boolean
}

export function BusinessJsonLd({ config, organization }: BusinessJsonLdProps) {
	const ld = organization ? buildOrganizationLdFromConfig(config) : buildLocalBusinessLd(config)
	if (!ld) return null
	return <JsonLd data={ld} />
}
